def _require(path: str, needle: str) -> None:
    file_path = ROOT / path
    if not file_path.exists():
        raise RuntimeError(f"Missing required file: {path}")
    text = file_path.read_text(encoding="utf-8")
    if needle not in text:
        raise RuntimeError(f"Preflight failed: {path} does not contain expected marker {needle!r}")


def preflight() -> None:
    _require("src/pegasus/workflows/compile.py", "race_bridge_plan = resolve_race_bridge_plan")
    _require("src/pegasus/workflows/compile.py", "attach_maternal_child_compile_fields")
    _require("src/pegasus/output/validate.py", "def _validate_race_bridge_contract")
    _require("src/pegasus/output/validate.py", "_validate_race_bridge_contract(root=root")
    _require("src/pegasus/output/cnes_sih_efg_bundle.py", "write_cnes_sih_fixture_efg_bundle")
    _require("src/pegasus/workflows/cnes_sih.py", "run_build_cnes_sih_fixture")
    _require("src/pegasus/core/schemas.py", "context_policy: list[str]")


def write_file(path: str, content: str) -> None:
    file_path = ROOT / path
    file_path.parent.mkdir(parents=True, exist_ok=True)
    file_path.write_text(content.rstrip() + "\n", encoding="utf-8")


def main() -> None:
    preflight()
    print("Slice 5B v2 preflight passed.")
    print("CREATE/REPLACE:")
    for path in FILES:
        print(f"  {path}")
    for path, content in FILES.items():
        write_file(path, content)
    print("Applied Slice 5B v2 compile-integrated CNES-ST/SIH-RD source-realism.")


if __name__ == "__main__":
    main()
